import { useState ,useRef} from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { addTask } from '../State/action-creators/index';
import addplus from './assets/Add_Plus.png'
import "../Style/InputForm.css"
import TaskCalendar from './TaskCalendar';
function TasksInputForm() {
    const [taskInput, setTaskInput] = useState({
      title:'',
      description:'',
      Category:'',
      Priorty:''

});
const selectRef = useRef(null);
const [searchCategory,setSearchCategory] =useState('');
const [searchPriorty,setSearchPriorty] =useState('');
  const dispatch = useDispatch();
  const tasks = useSelector((state) => state.tasks);
   const handleAddTask = () => {
//   if (taskInput.title.trim() === '' && taskInput.description.trim()==='' && taskInput.Category.trim()==='' && taskInput.Priorty.trim()==='') return;

    const newTask = {
      id: Date.now(),
      title:taskInput.title,
      description: taskInput.description,
      Category:taskInput.Category,
      Priorty:taskInput.Priorty,
      inProgress: true,
    };

    dispatch(addTask(newTask));
    setTaskInput({
      title:'',
      description:'',
      Category:'',
      Priorty:''

});
console.log(tasks.descriptions)
  };
    const handleChange = (e) => {
    const { name, value } = e.target;

    setTaskInput((prevData) => ({
      ...prevData,
      [name]: value,
    }));
  };
   const handleButtonClick = () => {
    if (selectRef.current) {
      selectRef.current.click(); // Opens the dropdown
    }
  }
  return (
  <>
    <div className='InputForm'>
      <TaskCalendar/>
        <input 
          className='TitleInputflied'
          type="text"
          name="title"
          value={taskInput.title}
          onChange={(e)=> setTaskInput((prevData) => ({
      ...prevData,
      title:e.target.value
    }))}
          placeholder="Type Title Of Task"
          
        />
        <input 
          className='DesInputflied'
          type="text"
          name='description'
          value={taskInput.description}
          onChange={(e)=>setTaskInput((prevData) => ({
      ...prevData,
      description:e.target.value
    }))}
          placeholder="Detail Of Your Task" />
       
    <div className='Categoryinput'>
      <select className='select-box' value={taskInput.Category} onChange={(e)=> setTaskInput((prevData) => ({
      ...prevData,
      Category:e.target.value
    }))} placeholder='By category'>
      <option value="select Catagory">select Catagory</option>
        <option value="Learning/working">Learning/working</option>
        <option value="Playing">Playing</option>
        <option value="eating">eating</option>
      </select>
    </div>
     <div className='Priortyinput'>
      <select className='select-box' value={taskInput.Priorty} onChange={(e)=> setTaskInput((prevData) => ({
      ...prevData,
      Priorty:e.target.value
    }))} placeholder='By priorty'>
        <option value="Low">Low</option>
        <option value="Mid">Mid</option>
        <option value="High">High</option>
      </select>
    </div>
  
    
                <button onClick={handleAddTask} className='AddButton'><img src={addplus} alt='addplus'></img></button>
    </div>

    <div className='SearchLists'>
    <form className='Category'>
      <select value={searchCategory} onChange={(e) => setSearchCategory(e.target.value)} placeholder='By category'>
        <option value="Learning/working">Learning/working</option>
        <option value="Playing">Playing</option>
        <option value="eating">eating</option>
      </select>
    </form>
     <form className='Priorty'>
      <select value={searchPriorty} onChange={(e) => setSearchPriorty(e.target.value)} placeholder='By priorty'>
        <option value="Low">Low</option>
        <option value="Mid">Mid</option>
        <option value="High">High</option>
      </select>
    </form>
  </div>
</>
  )
   }
export default TasksInputForm
